import pathlib,subprocess,json,hashlib
p=pathlib.Path('/srv/opentallas-scratch/codex/hostnative-clock-binding-20261009');p.mkdir(exist_ok=True)
sdc='# ot_rom_host_ingest block SDC append (stream ingest 2026-10-08).  Time unit = the library\'s (ps on ASAP7).\n# core_clk (ck, the die clock) comes from run_abi3_physical; clk_i = the ingest core clock = ck / 2 (own root);\n# clk_h = the host link user clock (1 GHz).  The three domains cross only through Gray-pointer async FIFOs and a\n# toggle-qualified static CSR, so they are asynchronous groups.  Host-face IO is timed against clk_h at 20 %.\ncreate_clock -name clk_i -period [expr {[get_property [get_clocks core_clk] period] * 2}] [get_ports clk_i]\ncreate_clock -name clk_h -period 1000 [get_ports clk_h]\nset_clock_uncertainty -setup 60 [get_clocks {clk_i clk_h}]\nset_clock_uncertainty -hold 25 [get_clocks {clk_i clk_h}]\nset_clock_groups -asynchronous -group [get_clocks core_clk] -group [get_clocks clk_i] -group [get_clocks clk_h]\nset ot_hing_ck [get_ports {clk_i clk_h}]\ncatch {unset_input_delay $ot_hing_ck}\nset ot_hing_in [get_ports {h_v h_cls[*] h_d[*] t_cr}]\nset ot_hing_out [get_ports {h_crn[*] t_v t_d[*]}]\ncatch {unset_input_delay $ot_hing_in}\ncatch {unset_output_delay $ot_hing_out}\nset_input_delay 200 -clock clk_h $ot_hing_in\nset_output_delay 200 -clock clk_h $ot_hing_out\nset_false_path -from [get_ports rst_n]\nputs "OT_HING clocks: clk_i = ck / 2, clk_h 1000, async groups"\n'
(p/'fixed.sdc').write_text(sdc)
mock='set period [lindex $argv 0]\nproc get_clocks {x} {return $x}\nproc get_property {x key} {global period;return $period}\nproc get_ports {x} {return $x}\nproc create_clock {args} {puts $args}\nforeach cmd {set_clock_uncertainty set_clock_groups unset_input_delay unset_output_delay set_input_delay set_output_delay set_false_path} {proc $cmd {args} {}}\nsource [lindex $argv 1]\n'
(p/'probe.tcl').write_text(mock)
cases=[]
for v in [730,833.333,1024]:
 r=subprocess.run(['tclsh',str(p/'probe.tcl'),str(v),str(p/'fixed.sdc')],capture_output=True,text=True);assert r.returncode==0,r.stderr
 line=r.stdout.splitlines()[0];actual=float(line.split('-period ')[1].split()[0]);assert abs(actual-2*v)<1e-8;cases.append({'core_period':v,'ingest_period':actual,'clk_period_defined':False,'rc':r.returncode})
receipt={'host':'ot-epyc1tb','cases':cases,'fixed_sdc_sha256':hashlib.sha256(sdc.encode()).hexdigest(),'verdict':'PASS','scope':'Tcl binding fixture only; no timing closure claim.'};(p/'receipt.json').write_text(json.dumps(receipt));print(json.dumps(receipt))
